library(shiny); library(bslib); library(DBI); library(RSQLite); library(data.table); library(ggplot2); library(DT); library(jsonlite); library(pomp)
source("R/config_params.R"); source("R/model_util.R"); source("R/model_simulator.R"); source("R/model_estimation.R"); source("R/model_decision.R"); source("R/db.R"); source("R/app_modules.R")
cfg<-hcf_config(); con<-db_connect()
ui<-page_fluid(theme=bs_theme(version=5,bootswatch="flatly"),tags$head(tags$link(rel="manifest",href="manifest.json"),tags$link(rel="stylesheet",href="styles.css"),tags$script("if('serviceWorker' in navigator) navigator.serviceWorker.register('service-worker.js');")),titlePanel("Health Capital Framework"),navset_tab(nav_panel("Player entry",mod_player_input_ui("entry")),nav_panel("Player dashboard",mod_dashboard_ui("dash")),nav_panel("Team dashboard",DTOutput("team"),disclaimer_ui()),nav_panel("Portfolio",textInput("newid","Player ID"),textInput("newname","Player name"),numericInput("newage","Age",27),checkboxInput("newhist","Prior injury"),actionButton("add","Add player")),nav_panel("Admin simulation",actionButton("seed","Seed synthetic season"),actionButton("validate","Run simulate-then-recover validation"),verbatimTextOutput("admin"))))
server<-function(input,output,session){mod_player_input_server("entry",con);mod_dashboard_server("dash",con,cfg);observeEvent(input$add,{db_upsert_player(con,data.frame(player_id=input$newid,player_name=input$newname,age=input$newage,prior_injury=as.integer(input$newhist),experience_years=0))});observeEvent(input$seed,{s<-simulate_season(cfg$squad_size,cfg$season_days,cfg);lapply(seq_len(nrow(s$profiles)),function(i)db_upsert_player(con,s$profiles[i,,drop=FALSE]));lapply(split(s$panel,s$panel$player_id),function(d)lapply(seq_len(nrow(d)),function(i)db_save_entry(con,as.list(d[i,,drop=FALSE]))));output$admin<-renderText("Synthetic panel seeded into SQLite.")});observeEvent(input$validate,{v<-simulate_then_recover(cfg,particles=300,mif_iterations=5);output$admin<-renderPrint(v$recovery)});output$team<-renderDT({p<-db_players(con);DT::datatable(p[,c("player_name","age","prior_injury")],rownames=FALSE)})}
shinyApp(ui,server)
